<script>
  import { onMount } from 'svelte';
  import { drawing, renderLab } from '../geometry-practice/drawings.js';
  export let topics; export let Q; export let rewards; export let chinese = false;
  const fresh = () => ({v:1,level:0,labs:Array(6).fill(false),solved:[],wrong:[],revisited:[],hintsUsed:[],attempts:{},current:0});
  let state=fresh(), reward=null, phase='lab', active=null, selection=[], why='', reviewMode=false, locked=false, feedback='', hint=false, storageOK=true, loaded=false;
  let labSelection=[], labReady=false, labFeedback='', labMode=0, labValue=45, parentOK=false, rewardNote='选项确定后，刮开属于你的奖励卡。';
  let writing='', checks=[false,false,false,false], writingStatus='只存当前浏览器，不上传。不用关键词打分，也不自动判断作文优劣。';
  $: key=chinese?'yoyo-chinese-v1':'yoyo-geometry-v1';
  $: rewardKey=chinese?'yoyo-chinese-reward-v1':'yoyo-geometry-reward-v1';
  $: pending=state.wrong.filter(id=>!state.revisited.includes(id));
  $: complete=state.solved.length===Q.length&&state.labs.every(Boolean)&&pending.length===0;
  $: lab=renderLab(state.level,labMode,labValue);
  $: title=chinese?'文字探险森林':'几何探险岛';
  function read(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{storageOK=false;return null}}
  function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{storageOK=false}}
  function save(){if(loaded)write(key,state)}
  function restore(raw){const s=fresh();if(!raw||raw.v!==1)return s;s.level=Number.isInteger(raw.level)&&raw.level>=0&&raw.level<6?raw.level:0;s.labs=topics.map((_,i)=>raw.labs?.[i]===true);for(const k of ['solved','wrong','revisited','hintsUsed'])s[k]=Array.isArray(raw[k])?[...new Set(raw[k].filter(n=>Number.isInteger(n)&&n>=0&&n<Q.length))]:[];s.revisited=s.revisited.filter(id=>s.wrong.includes(id)&&s.solved.includes(id));if(raw.attempts&&typeof raw.attempts==='object')for(const q of Q){const n=raw.attempts[q.id];if(Number.isInteger(n)&&n>=0&&n<100000)s.attempts[q.id]=n}return s}
  onMount(()=>{state=restore(read(key));const r=read(rewardKey);if(r&&Number.isInteger(r.choice)&&r.choice>=0&&r.choice<rewards.length)reward={choice:r.choice,revealed:r.revealed===true};if(chinese){const w=read('yoyo-chinese-writing-v1');writing=typeof w?.text==='string'?w.text.slice(0,4000):'';checks=checks.map((_,i)=>w?.checks?.[i]===true)}loaded=true;if(isComplete())phase='summary';else showLevel();const name=chinese?'chineseAdventure':'geometryAdventure';const api={questions:Q,topics,rewards,getState:()=>JSON.parse(JSON.stringify(state)),isComplete};window[name]=api;return()=>{if(window[name]===api)delete window[name]}});
  function isComplete(){return state.solved.length===Q.length&&state.labs.every(Boolean)&&!state.wrong.some(id=>!state.revisited.includes(id))}
  function showLevel(){if(!state.labs[state.level])showLab();else showQuestion()}
  function showLab(){phase='lab';labSelection=[];labReady=false;labFeedback='';labMode=0;labValue=state.level===4?370:state.level===1?40:45}
  function showQuestion(){phase='question';locked=false;feedback='';hint=false;selection=[];why='';active=reviewMode?Q[state.wrong.find(id=>!state.revisited.includes(id))]:Q.find(q=>q.t===state.level&&!state.solved.includes(q.id));if(!active)phase=reviewMode||state.level===5?'summary':'island'}
  function chooseLevel(i){state.level=i;state=state;reviewMode=false;save();showLevel()}
  function nextIsland(){chooseLevel(state.level+1)}
  function choose(n){if(locked)return;selection=(!chinese||active.kind==='single')?[n]:selection.includes(n)?selection.filter(x=>x!==n):[...selection,n]}
  function correct(){if(!chinese)return selection[0]===active.answer&&Number(why)===active.reason;if(active.kind==='single')return selection.length===1&&selection[0]===active.answer;if(active.kind==='order')return selection.length===active.answer.length&&selection.every((n,i)=>n===active.answer[i]);return selection.length===active.answer.length&&active.answer.every(n=>selection.includes(n))}
  function checkAnswer(){if(locked)return;if(!selection.length||(!chinese&&why==='')||(chinese&&active.kind==='order'&&selection.length!==active.opts.length)){feedback=!chinese?'先选一个答案，再选一句理由。慢慢来。':active.kind==='order'?'先把全部词块排好，再检查。':'先选出你的想法，再检查。';return}state.attempts[active.id]=(state.attempts[active.id]||0)+1;if(!correct()){if(!state.wrong.includes(active.id))state.wrong.push(active.id);state.revisited=state.revisited.filter(id=>id!==active.id);feedback=chinese?'再想一步：'+active.hint:selection[0]===active.answer?'答案选对了，再想想理由。'+active.hint:'还差一点，再观察条件。'+active.hint}else{if(!state.solved.includes(active.id))state.solved.push(active.id);if(reviewMode&&!state.revisited.includes(active.id))state.revisited.push(active.id);locked=true;feedback=(chinese?'✓ ':'✓ 想法和依据都对！')+active.explain}state=state;save()}
  function showHint(){hint=true;if(!state.hintsUsed.includes(active.id))state.hintsUsed.push(active.id);state=state;save()}
  function checkLab(){const t=topics[state.level];labReady=labSelection.length===t.evidence.length&&t.evidence.every(n=>labSelection.includes(n));labFeedback=labReady?'✓ 找到依据了！'+t.rule:'再读一次任务，看看选择的句子是否直接回答它。'+(t.evidence.length>1?'这次需要选两句。':'这次只需要选一句。')}
  function finishLab(){if(!labReady)return;state.labs[state.level]=true;state=state;save();showQuestion()}
  function touch(){labReady=true}
  function move(dir){const min=state.level===4?50:0,max=state.level===4?470:state.level===3&&labMode?90:180;labValue=Math.max(min,Math.min(max,labValue+dir*(state.level===4?10:5)));touch()}
  function toggle(){labMode=1-labMode;if(state.level===3)labValue=Math.min(labValue,labMode?90:180);touch()}
  function review(){reviewMode=true;showQuestion()}
  function resume(){reviewMode=false;state.level=Q.find(q=>!state.solved.includes(q.id)).t;state=state;save();showLevel()}
  function selectReward(i){if(!parentOK){rewardNote='先和家长商量，再勾选确认。';return}if(!confirm('确定选择“'+rewards[i].name+'”吗？本轮只能领这一份。'))return;reward={choice:i,revealed:false};write(rewardKey,reward)}
  function reveal(){if(!isComplete()||!reward)return;reward={...reward,revealed:true};write(rewardKey,reward)}
  function scratch(node){const ctx=node.getContext('2d');if(!ctx)return;ctx.fillStyle='#b9c9bd';ctx.fillRect(0,0,480,210);ctx.fillStyle='#294a3b';ctx.textAlign='center';ctx.font='bold 24px system-ui';ctx.fillText('✦ 刮开你的努力勋章 ✦',240,100);ctx.font='15px system-ui';ctx.fillText('每一次思考都在发光',240,135);let down=false;const cells=new Set();function rub(e){const r=node.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*480,y=(e.clientY-r.top)/r.height*210;ctx.globalCompositeOperation='destination-out';ctx.beginPath();ctx.arc(x,y,25,0,Math.PI*2);ctx.fill();for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){const gx=Math.floor(x/20)+dx,gy=Math.floor(y/20)+dy;if(gx>=0&&gx<24&&gy>=0&&gy<11)cells.add(gx+','+gy)}if(cells.size>105)reveal()}node.onpointerdown=e=>{down=true;node.setPointerCapture(e.pointerId);rub(e)};node.onpointermove=e=>{if(down)rub(e)};node.onpointerup=node.onpointercancel=()=>down=false;return{destroy(){node.onpointerdown=node.onpointermove=node.onpointerup=node.onpointercancel=null}}}
  function reset(){if(!confirm(chinese?'重新开始全部练习？进度会清空，已选奖励和表达小本仍然保留。':'重新开始全部练习？练习进度会清空，已选奖励仍然保留。'))return;state=fresh();reviewMode=false;save();showLevel()}
  function saveWriting(){write('yoyo-chinese-writing-v1',{text:writing.slice(0,4000),checks});writingStatus=storageOK?'已保存在当前浏览器。没有自动评分；请自查并和家长交流。':'无法保存，请把文字复制到安全的位置或写在纸上。'}
</script>
<svelte:head><title>{title} · 悠悠的学习之旅</title></svelte:head>
<header class="top"><a class="brand" href={chinese?'/learning/chinese/':'/learning/math/'}>← 悠悠的{chinese?'语文':'数学'}小站</a><span class="small">不用计时 · {chinese?'慢慢读，讲清楚':'可以随时休息'}</span></header>
<main><section class="hero"><div><span class="tag">悠悠的学习之旅 / {chinese?'语文':'数学'}</span><h1>{title}</h1><p>{chinese?'从一个小场景出发，点出证据，把词句排好，再带着方法读一段新文字。':'先动手，发现规律；再画图，说出理由。用六座小岛，把“看起来像”变成“我知道为什么”。'}</p><span class="small">6 个主题 · 30 道挑战 · {chinese?'证据点选 · 词句拼搭':'错题回访'} · 通关刮奖励</span></div><div class="island" aria-hidden="true">{chinese?'🌳':'🏝️'}</div></section>
<div id="storageNotice" class="warning" class:hidden={storageOK} role="status">当前浏览器无法可靠保存进度。你仍可练习，但关闭或刷新后可能丢失；奖励请让家长记录。</div>
<div class="layout"><aside class="panel side"><div class="eyebrow">我的探索地图</div><p id="progressText">已完成 {state.solved.length} / {Q.length} 道挑战</p><div class="meter" aria-hidden="true"><div id="progressBar" style:width={state.solved.length/Q.length*100+'%'}></div></div><nav class="map" id="map" aria-label="关卡地图">{#each topics as t,i}<button class="level" class:active={i===state.level} data-level={i} disabled={!loaded||(i>0&&Q.some(q=>q.t===i-1&&!state.solved.includes(q.id)))} onclick={()=>chooseLevel(i)}>{t.icon} {i+1}. {t.name}<span>{state.solved.filter(id=>Q[id].t===i).length} / 5 道 · {state.labs[i]?(chinese?'已找证据':'已探索'):(chinese?'先看场景':'先动手')}</span></button>{/each}</nav><p class="small">{chinese?'先点出场景证据，再挑战。答错不扣分。每站最后一道是新的应用情境。':'先完成动手探索，再挑战问题。答错不扣分，稍后换个顺序再想一次。'}</p><button id="reviewButton" class="soft" class:hidden={!pending.length} onclick={review}>{chinese?'同题回访':'回访易错题'}（{pending.length}）</button>{#if chinese}<button id="summaryButton" onclick={()=>phase='summary'}>查看学习手记</button>{/if}</aside>
<section class="panel" id="work" aria-live="polite">
{#if !loaded}<p>正在恢复当前浏览器中的探索记录…</p>
{:else if phase==='lab'}
<div class="steps"><span class="on">① {chinese?'场景找证据':'动手探索'}</span><span>② {chinese?'词句搭想法':'看图辨析'}</span><span>③ {chinese?'新情境应用':'说理迁移'}</span></div><div class="eyebrow">{topics[state.level].icon} 第 {state.level+1} {chinese?'站':'座岛'}</div><h2>{chinese?topics[state.level].name:topics[state.level].title}</h2>
{#if chinese}<div class="scene-art" aria-hidden="true">{topics[state.level].art}</div><p>{topics[state.level].task}</p><div class="scene">{#each topics[state.level].scene as line,i}<button class="evidence-line" class:chosen={labSelection.includes(i)} data-evidence={i} aria-pressed={labSelection.includes(i)} disabled={labReady} onclick={()=>labSelection=labSelection.includes(i)?labSelection.filter(n=>n!==i):[...labSelection,i]}>{line}</button>{/each}</div><div id="labFeedback" role="status" class:feedback={!!labFeedback} class:good={labReady}>{labFeedback}</div><div class="actions"><button class="primary" id="labCheck" disabled={labReady} onclick={checkLab}>检查场景证据</button><button class="primary" class:hidden={!labReady} id="labDone" onclick={finishLab}>带着方法开始挑战 →</button></div>
{:else}<p>{topics[state.level].intro}</p><div class="scene" id="labScene">{@html lab.d}</div><div id="labControls">{#if state.level===0||state.level===5}<div class="options">{#each state.level===0?['关闭两端','打开右端','打开两端']:['相邻拼接：30° + 45°','重合比较：45° − 30°'] as label,i}<button data-mode={i} onclick={()=>{labMode=i;touch()}}>{label}</button>{/each}</div>{:else}<label class="control">{state.level===4?'河岸上的到达位置':state.level===1?'张开角度':state.level===2?'整体旋转角度':'已知部分角度'}<input id="labRange" type="range" min={state.level===4?50:0} max={state.level===4?470:state.level===3&&labMode?90:180} step={state.level===4?10:5} bind:value={labValue} oninput={touch}></label><div class="actions"><button id="less" onclick={()=>move(-1)}>− 一小步</button><button id="more" onclick={()=>move(1)}>＋ 一小步</button>{#if state.level===2||state.level===3}<button id="toggle" onclick={toggle}>切换：{state.level===2?'垂直 / 平行':'平角 / 直角'}</button>{/if}</div>{/if}</div><p class="hint" id="labObservation">{lab.o}</p><div class="actions"><button class="primary" id="labDone" disabled={!labReady} onclick={finishLab}>我探索过了，开始挑战 →</button></div><p class="small">先尝试改变一次图形。可拖动滑块，也可点按钮操作。</p>{/if}
{:else if phase==='question'&&active}
<div class="steps"><span>① {chinese?'场景找证据':'动手探索'}</span><span class:on={active.id%5<(chinese?4:3)}>② {chinese?'词句搭想法':'看图辨析'}</span><span class:on={active.id%5>=(chinese?4:3)}>③ {chinese?'新情境应用':'说理迁移'}</span></div><div class="eyebrow">{reviewMode?'🌱 同题回访（不是新题测验）':topics[active.t].icon+' '+topics[active.t].name} · {active.id%5+1}/5</div><h2 id="questionTitle">{active.stem}</h2>
{#if chinese}<p class="small">{active.kind==='order'?'按顺序点词块；点上方已选词块可撤回。无需打字。':active.kind==='evidence'?'可以选多项；再点一次取消。全部选对才通过。':'选一个最符合本次任务的答案。'}</p>{#if active.passage}<div class="scene-text">{active.passage}</div>{/if}{:else}<div class="scene">{@html drawing(active.diagram)}</div>{/if}
{#if active.kind==='order'}<div class="order-line" id="orderLine" aria-label="你排出的句子">{#each selection as n,i}<button data-remove={i} disabled={locked} onclick={()=>selection=selection.filter((_,index)=>index!==i)}>{active.opts[n]} ↩</button>{:else}<span class="small">依次点下方词块，句子会出现在这里。</span>{/each}</div>{/if}
<div class="options" id="answers" role="group" aria-labelledby="questionTitle">{#each active.opts as option,i}{#if active.kind==='order'}<button class="option" data-piece={i} disabled={locked||selection.includes(i)} onclick={()=>selection=[...selection,i]}>{option}</button>{:else}<button class="option" class:selected={selection.includes(i)} data-answer={i} aria-pressed={selection.includes(i)} disabled={locked} onclick={()=>choose(i)}>{String.fromCharCode(65+i)}. {option}</button>{/if}{/each}</div>
{#if !chinese}<label class="control" for="reason">再想一步：你的依据是什么？<select id="reason" bind:value={why} disabled={locked}><option value="">请选择理由</option>{#each active.reasons as reason,i}<option value={String(i)}>{reason}</option>{/each}</select></label>{/if}
<div id="feedback" role="status" class:feedback={!!feedback} class:good={locked}>{feedback}</div><div class="actions"><button class="primary" id="check" disabled={locked} onclick={checkAnswer}>检查我的想法</button><button id="hintButton" disabled={locked} onclick={showHint}>给我一个提示</button>{#if active.kind==='order'}<button id="clearOrder" disabled={locked} onclick={()=>selection=[]}>清空重排</button>{/if}{#if locked}<button class="primary" id="next" onclick={showQuestion}>带着发现继续 →</button>{/if}</div><p id="hint" class="hint" class:hidden={!hint}>{hint?active.hint:''}</p>{#if !chinese}<p class="small">图形用于帮助思考。判断时以标注和题目条件为准，不用测量屏幕。</p>{/if}
{:else if phase==='island'}<div class="badge" aria-hidden="true">{topics[state.level].icon}</div><h2>{chinese?'这一站的发现，记住了吗？':'你把想法讲清楚了！'}</h2><p>{chinese?topics[state.level].rule:'休息一下也很好。下一座岛会带来新的发现。'}</p>{#if chinese}<p class="small">可以休息，也可以给家长说一句“我找到的依据是……”。</p>{/if}<div class="actions"><button class="primary" id="nextIsland" onclick={nextIsland}>前往 {topics[state.level+1].name} →</button><button id="redoLab" onclick={showLab}>{chinese?'再看一次场景':'再玩动手探索'}</button></div>
{:else if phase==='summary'}<div class="eyebrow">探索手记{chinese?' · 不是能力等级':''}</div><h2>{complete?(chinese?'🎉 六站全部点亮！':'🎉 六座岛，全部点亮！'):'🌱 看看我们的学习足迹'}</h2><div class="stats"><div class="stat"><b>{state.solved.length}</b>完成挑战</div><div class="stat"><b>{state.solved.filter(id=>!state.wrong.includes(id)&&!state.hintsUsed.includes(id)).length}</b>首次无提示答对</div><div class="stat"><b>{state.hintsUsed.length}</b>主动看提示的题数</div><div class="stat"><b>{state.wrong.length}</b>曾经答错的题数</div></div><p>{chinese?(pending.length?'还有 '+pending.length+' 道同题回访。它是复习，不是独立掌握证明。':complete?'本轮挑战与同题回访已完成。隔天换一篇短文，再试一次；默写与作文另需纸笔、自查和家长反馈。':'还有 '+(Q.length-state.solved.length)+' 道挑战等待探索。'):(pending.length?'还有 '+pending.length+' 道易错题等待回访。这是同题复习，请遮住提示再想一次；另有最后一岛的新题迁移挑战。完成全部挑战和回访才解锁奖励。':complete?'你已经完成挑战和必要的同题回访。隔天换种图形再试一次，会更扎实。':'同题回访已完成，还有 '+(Q.length-state.solved.length)+' 道挑战等待探索。')}</p><ul>{#each topics as t,i}<li>{t.icon} {t.name}：{state.solved.filter(id=>Q[id].t===i).length===0?'未开始':state.solved.filter(id=>Q[id].t===i).length===5?'全部完成（5/5）':'已完成 '+state.solved.filter(id=>Q[id].t===i).length+'/5'}。{#if !chinese}{state.wrong.filter(id=>Q[id].t===i).length?'有 '+state.wrong.filter(id=>Q[id].t===i).length+' 道曾出错，建议隔天再说一遍依据。':state.solved.filter(id=>Q[id].t===i).length===5?'隔天还可换题检验。':'继续探索，不着急。'}{/if}</li>{/each}</ul><div class="actions">{#if pending.length}<button class="primary" id="startReview" onclick={review}>开始{chinese?'同题':'易错'}回访 →</button>{/if}{#if complete}<button class="primary" id="rewardButton" onclick={()=>phase='reward'}>领取{chinese?'':'我的'}通关奖励 🎁</button>{:else if state.solved.length<Q.length}<button class="primary" id="resumeChallenge" onclick={resume}>继续未完成挑战 →</button>{/if}</div>
{:else if phase==='reward'}<div class="eyebrow">给坚持思考的你</div><h2>一份小小的通关礼 🎁</h2><p>先和家长商量，再选一项。选定后不能在本浏览器重新抽换，不花钱买机会，也没有“谢谢参与”。</p><div id="rewardContent">{#if !reward}<div class="reward-options">{#each rewards as r,i}<button class="reward" data-reward={i} onclick={()=>selectReward(i)}><span style="font-size:28px">{r.icon}</span><br><b>{r.name}</b><br><span class="small">预算 ≤ {r.limit} 元</span></button>{/each}</div><label class="control"><span><input type="checkbox" id="parentOK" bind:checked={parentOK}> 已和家长商量，由家长兑现</span></label><p class="small" id="rewardNote">{rewardNote}</p>{:else}<div class="scratch"><div class="prize" id="prize" aria-hidden={!reward.revealed}><span style="font-size:38px">{rewards[reward.choice].icon}</span><b>{rewards[reward.choice].name}</b><span>{rewards[reward.choice].desc}</span></div>{#if !reward.revealed}<canvas use:scratch id="scratch" width="480" height="210" aria-label="奖励刮刮卡，用手指或鼠标刮开；也可使用下面的揭晓按钮"></canvas>{/if}</div>{#if reward.revealed}<p class="feedback good">已领取 · 请把奖励卡给家长看。你的认真思考，比奖品更闪亮。</p>{:else}<p class="small">用手指或鼠标刮一刮，探索卡片。也可以不用拖动，直接揭晓。</p><button class="primary" id="reveal" onclick={reveal}>无障碍揭晓奖励</button>{/if}{/if}</div><p class="small">奖励由家长确认并兑现，预算上限不是商品报价；不会自动购买或付款。重新练习不会重发奖励。</p><button id="backSummary" onclick={()=>phase='summary'}>查看探索手记</button>{/if}
</section></div>
{#if chinese}<details class="panel notebook"><summary>✍️ 我的表达小本（可选，不影响通关）</summary><p>任选校园的一处地方，写 3—5 句话：介绍在哪里，用两个观察细节说明特点，再说推荐理由。不会写的字先作标记，完成后查字订正。</p><label for="writing">在这里写，或拿纸笔写后口头分享：</label><textarea id="writing" maxlength="4000" placeholder="我想推荐……" bind:value={writing} oninput={(e)=>{writing=e.currentTarget.value;saveWriting()}}></textarea><p class="small" id="writingStatus">{writingStatus}</p><div class="control">{#each ['我说清了推荐的地方与理由。','我写了亲眼看见或听见的细节。','我检查了字形、标点、语句和事实。','我读给家长听，请对方说出印象最清楚的一句。'] as label,i}<label><input type="checkbox" class="selfcheck" bind:checked={checks[i]} onchange={(e)=>{checks[i]=e.currentTarget.checked;checks=[...checks];saveWriting()}}> {label}</label>{/each}</div><details><summary>写完后看一个原创例子（不是唯一答案）</summary><p>我想推荐校园的小花园。清晨，叶尖挂着亮晶晶的露珠，微风送来淡淡的花香。我们可以沿着小路慢慢走，看看花朵每天的新变化。请不要摘花，把美丽留给下一位同学。</p><p class="small">请比较“对象、细节、顺序、理由”，不必照抄。纸笔默写和开放表达需要孩子自查、家长或老师反馈。</p></details></details>{/if}
<slot name="parents" {reset}/></main><footer class="small">🌿 {chinese?'读出画面，找到依据，把想法讲清楚。':'慢慢想，说出来，再试一次。每一次发现都值得开心。'} <a href="/learning/">返回学习之旅</a></footer>
